local WarpBeamMaker = {}
local PRODUCTS = {
    iron_warp_beam = { name = "Železna osnovna gredica", ironCost = 3, woodCost = 4, leatherCost = 1, time = 6, cost = 185, prestige = 4, happiness = 2, description = "Železna osnovna gredica za statve." },
    bronze_warp_beam = { name = "Bronasta osnovna gredica", bronzeCost = 3, ironCost = 1, woodCost = 4, leatherCost = 1, time = 8, cost = 445, prestige = 6, happiness = 3, description = "Bronasta osnovna gredica za široke statve." },
    silver_warp_beam = { name = "Srebrna osnovna gredica", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 4, leatherCost = 1, time = 12, cost = 1070, prestige = 11, happiness = 4, description = "Srebrna osnovna gredica za plemiške statve." },
    gilded_warp_beam = { name = "Pozlačena osnovna gredica", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 16, cost = 2300, prestige = 20, happiness = 5, description = "Pozlačena osnovna gredica za dvorne statve." },
    jewel_set_warp_beam = { name = "Draguljasta osnovna gredica", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 20, cost = 4950, prestige = 36, happiness = 7, description = "Draguljasta osnovna gredica za kraljevske statve." },
    royal_sovereign_warp_beam = { name = "Kraljevski suverena osnovna gredica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 5, leatherCost = 1, time = 27, cost = 10600, prestige = 69, happiness = 13, description = "Suverena osnovna gredica z biseri za krono." },
}
local BUILDINGS = {
    warpbeam_workshop = { name = "Gredična delavnica", cost = { gold = 370, wood = 195, stone = 145, iron = 8 }, upkeep = 7, qualityBonus = 5 },
    warpbeam_house = { name = "Gredična hiša", cost = { gold = 1285, wood = 380, stone = 290, silver = 8, iron = 8 }, upkeep = 27, qualityBonus = 18 },
    master_warpbeam_atelier = { name = "Mojstrski gredični atelje", cost = { gold = 3200, wood = 440, stone = 545, silver = 39, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_warpbeam_palace = { name = "Suverena gredična palača", cost = { gold = 13600, wood = 670, stone = 865, gold = 88, jewel = 20 }, upkeep = 263, qualityBonus = 55, prestigeBonus = 50 },
}
WarpBeamMaker.ironStock = 14; WarpBeamMaker.bronzeStock = 12; WarpBeamMaker.woodStock = 18; WarpBeamMaker.leatherStock = 8; WarpBeamMaker.silverStock = 8; WarpBeamMaker.goldStock = 6; WarpBeamMaker.jewelStock = 4; WarpBeamMaker.pearlStock = 4
WarpBeamMaker.productStock = {}; WarpBeamMaker.buildings = {}; WarpBeamMaker.maker = nil; WarpBeamMaker.activeMaking = {}; WarpBeamMaker.totalProducts = 0; WarpBeamMaker.dayTimer = 0
function WarpBeamMaker.init() WarpBeamMaker.ironStock=14; WarpBeamMaker.bronzeStock=12; WarpBeamMaker.woodStock=18; WarpBeamMaker.leatherStock=8; WarpBeamMaker.silverStock=8; WarpBeamMaker.goldStock=6; WarpBeamMaker.jewelStock=4; WarpBeamMaker.pearlStock=4; WarpBeamMaker.productStock={}; WarpBeamMaker.buildings={}; WarpBeamMaker.maker=nil; WarpBeamMaker.activeMaking={}; WarpBeamMaker.totalProducts=0; WarpBeamMaker.dayTimer=0; print("[WarpBeamMaker] Royal Warp Beam Maker System initialized (6 products, 4 buildings)") end
function WarpBeamMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WarpBeamMaker.maker={name=n or ("Gredičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gredičar najet: %s (spretnost: %d)",WarpBeamMaker.maker.name,s),"success") end; return true end
function WarpBeamMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WarpBeamMaker.build(id) local ok,e=WarpBeamMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WarpBeamMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WarpBeamMaker.getQualityBonus() local b=0; for _,bd in ipairs(WarpBeamMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WarpBeamMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and WarpBeamMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and WarpBeamMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and WarpBeamMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and WarpBeamMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WarpBeamMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WarpBeamMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WarpBeamMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WarpBeamMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WarpBeamMaker.buildings==0 then return false,"Potrebna gredična delavnica" end; if not WarpBeamMaker.maker then return false,"Potreben gredičar" end; return true end
function WarpBeamMaker.make(pt,qty) qty=qty or 1; local ok,e=WarpBeamMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then WarpBeamMaker.ironStock=WarpBeamMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then WarpBeamMaker.bronzeStock=WarpBeamMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then WarpBeamMaker.woodStock=WarpBeamMaker.woodStock-d.woodCost*qty end; if d.leatherCost then WarpBeamMaker.leatherStock=WarpBeamMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WarpBeamMaker.silverStock=WarpBeamMaker.silverStock-d.silverCost*qty end; if d.goldCost then WarpBeamMaker.goldStock=WarpBeamMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WarpBeamMaker.jewelStock=WarpBeamMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WarpBeamMaker.pearlStock=WarpBeamMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WarpBeamMaker.maker then t=math.max(1,t-math.floor(WarpBeamMaker.maker.skill/13)) end; table.insert(WarpBeamMaker.activeMaking,{id="warpbeam_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WarpBeamMaker.completeMaking(m) local q=1.0+(WarpBeamMaker.getQualityBonus()/100); if WarpBeamMaker.maker then q=q+(WarpBeamMaker.maker.skill/140) end; q=math.min(2.5,q); WarpBeamMaker.productStock[m.productType]=(WarpBeamMaker.productStock[m.productType] or 0)+m.quantity; WarpBeamMaker.totalProducts=WarpBeamMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WarpBeamMaker.maker then WarpBeamMaker.maker.itemsMade=WarpBeamMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WarpBeamMaker.maker.skill=math.min(100,WarpBeamMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gredica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"warpbeam.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function WarpBeamMaker.update(dt) if not _G.state then return end; WarpBeamMaker.dayTimer=WarpBeamMaker.dayTimer+dt; if WarpBeamMaker.dayTimer>=30 then WarpBeamMaker.dayTimer=0; for i=#WarpBeamMaker.activeMaking,1,-1 do local m=WarpBeamMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WarpBeamMaker.completeMaking(m); table.remove(WarpBeamMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WarpBeamMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WarpBeamMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WarpBeamMaker.getStats() return {ironStock=WarpBeamMaker.ironStock,bronzeStock=WarpBeamMaker.bronzeStock,woodStock=WarpBeamMaker.woodStock,leatherStock=WarpBeamMaker.leatherStock,silverStock=WarpBeamMaker.silverStock,goldStock=WarpBeamMaker.goldStock,jewelStock=WarpBeamMaker.jewelStock,pearlStock=WarpBeamMaker.pearlStock,productStock=WarpBeamMaker.productStock,numBuildings=#WarpBeamMaker.buildings,hasMaker=WarpBeamMaker.maker~=nil,makerName=WarpBeamMaker.maker and WarpBeamMaker.maker.name or "—",makerSkill=WarpBeamMaker.maker and WarpBeamMaker.maker.skill or 0,activeMaking=#WarpBeamMaker.activeMaking,totalProducts=WarpBeamMaker.totalProducts} end
return WarpBeamMaker
